package trail

import (
	"testing"
	"time"
)

// TestStore_UpdateStatus verifies that updating only the status field
// persists correctly and doesn't affect other fields.
func TestStore_UpdateStatus(t *testing.T) {
	t.Parallel()
	repo := initTestRepo(t)
	store := NewStore(repo)

	now := time.Now().Truncate(time.Second)
	id, err := GenerateID()
	if err != nil {
		t.Fatalf("GenerateID() error = %v", err)
	}

	meta := &Metadata{
		TrailID:   id,
		Branch:    "feature/status-test",
		Base:      "main",
		Title:     "Status Test",
		Body:      "Test body",
		Status:    StatusDraft,
		Author:    "tester",
		Assignees: []string{"alice"},
		Labels:    []string{"bug"},
		CreatedAt: now,
		UpdatedAt: now,
	}
	if err := store.Write(meta, nil, nil); err != nil {
		t.Fatalf("Write() error = %v", err)
	}

	// Simulate runTrailUpdate with --status flag only
	// This mirrors the exact code path in trail_cmd.go lines 454-472
	statusStr := "open"
	title := ""    // not provided via flag
	body := ""     // not provided via flag

	err = store.Update(id, func(m *Metadata) {
		if statusStr != "" {
			m.Status = Status(statusStr)
		}
		if title != "" {
			m.Title = title
		}
		if body != "" {
			m.Body = body
		}
	})
	if err != nil {
		t.Fatalf("Update() error = %v", err)
	}

	// Read back and verify
	updated, _, _, err := store.Read(id)
	if err != nil {
		t.Fatalf("Read() error = %v", err)
	}
	if updated.Status != StatusOpen {
		t.Errorf("Status = %q, want %q", updated.Status, StatusOpen)
	}
	if updated.Title != "Status Test" {
		t.Errorf("Title changed to %q, want %q", updated.Title, "Status Test")
	}
	if updated.Body != "Test body" {
		t.Errorf("Body changed to %q, want %q", updated.Body, "Test body")
	}
	if len(updated.Labels) != 1 || updated.Labels[0] != "bug" {
		t.Errorf("Labels changed to %v, want [bug]", updated.Labels)
	}
}

// TestStore_UpdateStatusThroughAllStates tests updating status through
// every valid status value.
func TestStore_UpdateStatusThroughAllStates(t *testing.T) {
	t.Parallel()
	repo := initTestRepo(t)
	store := NewStore(repo)

	now := time.Now().Truncate(time.Second)
	id, err := GenerateID()
	if err != nil {
		t.Fatalf("GenerateID() error = %v", err)
	}

	meta := &Metadata{
		TrailID:   id,
		Branch:    "feature/all-states",
		Base:      "main",
		Title:     "State Machine Test",
		Status:    StatusDraft,
		Author:    "tester",
		Assignees: []string{},
		Labels:    []string{},
		CreatedAt: now,
		UpdatedAt: now,
	}
	if err := store.Write(meta, nil, nil); err != nil {
		t.Fatalf("Write() error = %v", err)
	}

	// Walk through all statuses
	statuses := []Status{StatusOpen, StatusInProgress, StatusInReview, StatusMerged, StatusClosed, StatusDraft}
	for _, targetStatus := range statuses {
		statusStr := string(targetStatus)
		err := store.Update(id, func(m *Metadata) {
			if statusStr != "" {
				m.Status = Status(statusStr)
			}
		})
		if err != nil {
			t.Fatalf("Update to %q error = %v", targetStatus, err)
		}

		updated, _, _, err := store.Read(id)
		if err != nil {
			t.Fatalf("Read after update to %q error = %v", targetStatus, err)
		}
		if updated.Status != targetStatus {
			t.Errorf("After update to %q: got %q", targetStatus, updated.Status)
		}
	}
}

// TestStore_FindByBranchThenUpdate tests the full lookup-then-update flow
// that runTrailUpdate uses.
func TestStore_FindByBranchThenUpdate(t *testing.T) {
	t.Parallel()
	repo := initTestRepo(t)
	store := NewStore(repo)

	now := time.Now().Truncate(time.Second)
	id, err := GenerateID()
	if err != nil {
		t.Fatalf("GenerateID() error = %v", err)
	}

	meta := &Metadata{
		TrailID:   id,
		Branch:    "feature/lookup-update",
		Base:      "main",
		Title:     "Lookup Update Test",
		Status:    StatusDraft,
		Author:    "tester",
		Assignees: []string{},
		Labels:    []string{},
		CreatedAt: now,
		UpdatedAt: now,
	}
	if err := store.Write(meta, nil, nil); err != nil {
		t.Fatalf("Write() error = %v", err)
	}

	// Step 1: FindByBranch (same as runTrailUpdate)
	found, err := store.FindByBranch("feature/lookup-update")
	if err != nil {
		t.Fatalf("FindByBranch() error = %v", err)
	}
	if found == nil {
		t.Fatal("FindByBranch() returned nil")
	}

	// Step 2: Update using the found trail ID (same as runTrailUpdate)
	err = store.Update(found.TrailID, func(m *Metadata) {
		m.Status = StatusInProgress
	})
	if err != nil {
		t.Fatalf("Update() error = %v", err)
	}

	// Step 3: Verify by reading directly
	updated, _, _, err := store.Read(id)
	if err != nil {
		t.Fatalf("Read() error = %v", err)
	}
	if updated.Status != StatusInProgress {
		t.Errorf("Status = %q, want %q", updated.Status, StatusInProgress)
	}

	// Step 4: Also verify via FindByBranch again (simulates trail list/show after update)
	found2, err := store.FindByBranch("feature/lookup-update")
	if err != nil {
		t.Fatalf("FindByBranch() second call error = %v", err)
	}
	if found2 == nil {
		t.Fatal("FindByBranch() returned nil after update")
	}
	if found2.Status != StatusInProgress {
		t.Errorf("FindByBranch after update: Status = %q, want %q", found2.Status, StatusInProgress)
	}
}

